import os, json, re, hashlib

ROOT = 'D:/repository'
SEL = r'C:/Users/Administrator/.dsh/cache/memory-audit/select.json'

d = json.load(open(SEL, encoding='utf-8'))
cands = d['candidates']

# --- verify body hash consistency (content from OpenViking at select time) ---
for c in cands:
    h = hashlib.sha256(c['content'].encode('utf-8')).hexdigest()[:16]
    c['_hash_ok'] = (h == c['body_sha256_16'])

# --- build file index (basename -> list of full paths), skip heavy dirs ---
SKIP = {'.git', 'node_modules', 'dist', '__pycache__', '.svn', 'vendor'}
EXTS = ('.vue', '.js', '.py', '.mjs', '.md', '.json', '.yml', '.yaml', '.scss', '.ts')
index = {}
for dp, dn, fn in os.walk(ROOT):
    dn[:] = [x for x in dn if x not in SKIP]
    for f in fn:
        if f.endswith(EXTS):
            index.setdefault(f, []).append(os.path.join(dp, f))

path_re = re.compile(r'(?:[\w\-.]+\/)*[\w\-.]+\.(?:vue|js|py|mjs|md|json|yml|yaml|scss|ts)')
tick_re = re.compile(r'`([^`]{3,})`')

report = []
for i, c in enumerate(cands):
    body = c['content']
    # candidate file basenames
    paths = set()
    for m in path_re.findall(body):
        paths.add(m.split('/')[-1])
    # symbols: backtick code fragments, keep meaningful ones
    syms = [s.strip() for s in tick_re.findall(body)]
    syms = [s for s in syms if any(ch.isalpha() for ch in s) and len(s) <= 60]
    # find matching local files
    found = {}
    for b in list(paths):
        if b in index:
            found[b] = index[b][:6]
    # check symbols across found files' contents
    matched_syms = {}
    hits_samples = {}
    for b, flist in found.items():
        text = ''
        for fp in flist[:4]:
            try:
                text += open(fp, encoding='utf-8', errors='ignore').read()
            except Exception:
                pass
        ms = [s for s in syms if s in text]
        if ms:
            matched_syms[b] = ms[:8]
    report.append({
        'n': i + 1,
        'uri': c['uri'],
        'sha': c['body_sha256_16'],
        'hash_ok': c['_hash_ok'],
        'paths_mentioned': sorted(paths),
        'files_found': {k: [p.replace(ROOT + '/', '') for p in v] for k, v in found.items()},
        'sym_matches': matched_syms,
    })

out = r'C:/Users/Administrator/.dsh/cache/memory-audit/verify_report.json'
json.dump(report, open(out, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print('index files:', len(index), 'report:', out)
print('hash_ok all:', all(r['hash_ok'] for r in report))

